head.script:


	scwin.trigger1_onclick = function(e) {

        grid1.setCellDisabled(0,0,true);
        grid1.setCellDisabled(1,0,true);
        grid1.setCellDisabled(3,0,true);
        grid1.setCellDisabled(75,0,true);
        grid1.setCellDisabled(219,0,true);
        grid1.setCellDisabled(229,0,true);
        grid1.setCellDisabled(309,0,true);
        grid1.setCellDisabled(310,0,true);

	};

    scwin.checkVal = function() {
		return WebSquare.util.getInstance().indexOf("<b>&lt;elagSelCat</b></font>>0<font color='blue'><b>&lt;/elagSelCat&gt;</b>") == 228541;
    };
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_h_col1').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
